package com.hiretrack.controller;import com.hiretrack.entity.Interview;import com.hiretrack.repository.*;import com.hiretrack.service.CurrentUser;import org.springframework.web.bind.annotation.*;import java.time.LocalDateTime;import java.util.*;@RestController @RequestMapping("/api/interviews")public class InterviewController{private final InterviewRepository repo;private final ApplicationRepository apps;private final CurrentUser current;public InterviewController(InterviewRepository r,ApplicationRepository a,CurrentUser c){repo=r;apps=a;current=c;}public record Request(Long applicationId,String roundName,LocalDateTime interviewDate,String interviewType,String meetingLink,String notes){}private Map<String,Object> dto(Interview i){return Map.of("id",i.getId(),"roundName",i.getRoundName()==null?"":i.getRoundName(),"interviewDate",i.getInterviewDate()==null?"":i.getInterviewDate(),"interviewType",i.getInterviewType()==null?"":i.getInterviewType(),"meetingLink",i.getMeetingLink()==null?"":i.getMeetingLink(),"notes",i.getNotes()==null?"":i.getNotes(),"application",Map.of("id",i.getApplication().getId(),"companyName",i.getApplication().getCompanyName(),"jobRole",i.getApplication().getJobRole()));}@GetMapping public List<Map<String,Object>> all(){return repo.findAllByApplicationUserIdOrderByInterviewDateAsc(current.get().getId()).stream().map(this::dto).toList();}@PostMapping public Map<String,Object> create(@RequestBody Request r){var a=apps.findByIdAndUserId(r.applicationId(),current.get().getId()).orElseThrow(()->new NoSuchElementException("Application not found"));Interview i=new Interview();i.setApplication(a);i.setRoundName(r.roundName());i.setInterviewDate(r.interviewDate());i.setInterviewType(r.interviewType());i.setMeetingLink(r.meetingLink());i.setNotes(r.notes());return dto(repo.save(i));}}